<script>
import{api,post,money,date}from '../api'
import QRCode from 'qrcode'
export default{data:()=>({items:[],busy:true,error:'',qr:''}),computed:{tickets(){return this.$route.path==='/entradas'}},async mounted(){await this.load()},methods:{money,date,async load(){this.busy=true;try{this.items=await api(this.tickets?'/my/tickets':'/my/notifications')}catch(e){this.error=e.message}finally{this.busy=false}},async showQR(ticket){this.error='';try{this.qr=await QRCode.toDataURL(ticket.ticketId,{width:260,margin:2})}catch{this.error='No se pudo generar el QR.'}},async mark(item){try{await post('/my/notifications/'+item.id+'/read',{});item.read=true}catch(e){this.error=e.message}}}}
</script>
<template><q-page class="container"><div class="eyebrow">TU CUENTA</div><h1 class="page-heading">{{tickets?'Mis entradas':'Tus notificaciones'}}</h1><p>{{tickets?'Tus vouchers y el estado de cada entrada.':'Novedades sobre tus eventos, en un solo lugar.'}}</p><q-banner v-if="error" class="error" role="alert">{{error}}</q-banner><div v-if="busy" class="empty"><q-spinner/> Cargando…</div><div v-else-if="!items.length&&!error" class="empty">{{tickets?'Todavía no tienes entradas registradas.':'No tienes notificaciones.'}}</div><div class="personal-list"><article class="surface" v-for="item in items" :key="tickets?item.ticketId:item.id"><template v-if="tickets"><q-badge :color="item.status==='Válida'?'primary':'grey'">{{item.status}}</q-badge><h3>{{item.event}}</h3><p>{{date(item.startDate)}} · {{item.city}}</p><p>{{item.venue}} · {{item.address}}</p><p>Titular: {{item.holder}} · {{money(item.price,item.currency)}}</p><small>Referencia: {{item.shortCode}}</small><p v-if="item.refundStatus==='Pendiente'">Pendiente de reembolso · {{item.cancellationReason}}</p><q-btn no-caps outline color="primary" label="Mostrar QR" :disable="item.status!=='Válida'||item.eventStatus==='Cancelado'" @click="showQR(item)"/><router-link :to="'/evento/'+item.eventId">Ver evento</router-link></template><template v-else><q-badge v-if="!item.read" color="secondary">Nueva</q-badge><h3>{{item.title}}</h3><p>{{item.message}}</p><small>{{date(item.createdAt)}}</small><q-btn v-if="!item.read" flat no-caps label="Marcar como leída" @click="mark(item)"/></template></article></div><q-dialog :model-value="!!qr" @update:model-value="qr=''"><q-card class="q-pa-lg text-center"><h3>Tu entrada digital</h3><img :src="qr" alt="Código QR de la entrada" width="260" height="260"><p>Presenta este QR al ingresar.</p><q-btn flat label="Cerrar" @click="qr=''"/></q-card></q-dialog></q-page></template>
